import java.util.ArrayList;

public class CertificadorFEL extends Integracion
        implements Consultable, Documentable, Auditable {

    // ATRIBUTOS
    // Eventos guarda el historial de auditoria
    // de los documentos generados por el certificador.

    private ArrayList<Evento> eventos;


    // CONSTRUCTOR VACIO
    // Inicializa los atributos comunes con super()
    // y crea una lista vacia para guardar los eventos.

    public CertificadorFEL() {
        super();
        eventos = new ArrayList<Evento>();
    }


    // CONSTRUCTOR COMPLETO
    // Envia los datos generales a Integracion.
    // Despues inicializa el historial de eventos.

    public CertificadorFEL(String id, String nombre,
                           int latencia, boolean listo,
                           String configuracion) {

        super(id, nombre, latencia, listo, configuracion);

        eventos = new ArrayList<Evento>();
    }

    //Nuevo estados
    @Override
    public String consultarEstado() {

        if (listo) {
            return "Conectado";
        }
        else {
            return "Desconectado";
        }
    }


    // Override e implementar generar documento

    @Override
    public String generarDocumento(String datos) {
        // Comprueba que la integracion este disponible.
        if (!listo) {
            registrarEvento(new Evento("No se pudo generar el documento porque la integracion no esta disponible", "Documento", false));
            return "No se pudo generar el documento.";
        }

        // Comprueba que se hayan recibido datos
        if (datos == null) {
            registrarEvento(new Evento("No se recibieron datos para generar el documento", "Documento", false));
            return "No se pudo generar el documento.";
        }

		//Debe tener datos
        if (datos.isEmpty()) {
            registrarEvento(new Evento("Los datos del documento estan vacios", "Documento", false));
            return "No se pudo generar el documento.";
        }

        // Construir factura
        String documento = "\nFACTURA ELECTRONICA SIMULADA"
            + "\nCertificador: " + nombre
            + "\nID de integracion: " + id
            + "\nDatos: " + datos
            + "\nEstado: Generada";

        // Registra que el documento fue generado.
        registrarEvento(new Evento("Documento generado correctamente", "Documento", true));
        return documento;
    }

    // Agregar al evento

    @Override
    public void registrarEvento(Evento evento) {

        if (evento != null) {
            eventos.add(evento);
        }
    }


    // Mostrar los eventos

    @Override
    public ArrayList<Evento> consultarHistorialEventos() {

        return new ArrayList<Evento>(eventos);
    }


    // Override del toString
    @Override
    public String toString() {

        return super.toString();
    }
}
